mapper.select:
SELECT *
FROM shopion.tOrdSlnkTransDetail
WHERE TransId = #{transId}
AND TransDetailNo = #{transDetailNo}

mapper.update:
UPDATE shopion.tOrdSlnkTransDetail SET
    ResultState = #{resultState}, ResultMsg = #{resultMsg}, OrderNo = #{orderNo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE TransId = #{transId}
AND TransDetailNo = #{transDetailNo}

mapper.delete:
DELETE FROM shopion.tOrdSlnkTransDetail
WHERE TransId = #{transId}
AND TransDetailNo = #{transDetailNo}
